import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.junit.Assert.*;

public class StartAutoLoadPolicyTests {

    private static final String TEST_MODEL_PATH = "src/test/resources/model.conf";
    private static final String TEST_POLICY_PATH = "src/test/resources/policy_test.csv";

    @Before
    public void setUp() throws IOException {
        // Create model file
        File modelFile = new File(TEST_MODEL_PATH);
        if (!modelFile.exists()) {
            modelFile.getParentFile().mkdirs();
            try (FileWriter writer = new FileWriter(modelFile)) {
                writer.write("[request_definition]\n");
                writer.write("r = sub, obj, act\n\n");
                writer.write("[policy_definition]\n");
                writer.write("p = sub, obj, act\n\n");
                writer.write("[role_definition]\n");
                writer.write("g = _, _\n\n");
                writer.write("[policy_effect]\n");
                writer.write("e = some(where (p.eft == allow))\n\n");
                writer.write("[matchers]\n");
                writer.write("m = r.sub == p.sub && r.obj == p.obj && r.act == p.act");
            }
        }

        // Create initial policy file
        createPolicyFile("p, alice, data1, read\n");
    }

    @After
    public void tearDown() throws IOException {
        File modelFile = new File(TEST_MODEL_PATH);
        if (modelFile.exists()) {
            Files.delete(modelFile.toPath());
        }
        File policyFile = new File(TEST_POLICY_PATH);
        if (policyFile.exists()) {
            Files.delete(policyFile.toPath());
        }
    }

    private void createPolicyFile(String content) throws IOException {
        File policyFile = new File(TEST_POLICY_PATH);
        try (FileWriter writer = new FileWriter(policyFile)) {
            writer.write(content);
        }
    }

    @Test
    public void testStartAutoLoadPolicyWithFileAdapter() {
        SyncedEnforcer enforcer = new SyncedEnforcer(TEST_MODEL_PATH, TEST_POLICY_PATH);

        // Start auto load
        enforcer.startAutoLoadPolicy(100);

        // Verify thread is running by checking internal state
        assertTrue("Auto load should be running", enforcer.isAutoLoadingRunning());

        // Wait a bit to let the loop execute at least once
        sleep(300);

        // Clean up
        enforcer.stopAutoLoadPolicy();
        assertFalse("Auto load should be stopped", enforcer.isAutoLoadingRunning());
    }

    @Test
    public void testStartAutoLoadPolicyWithAdapter() {
        Adapter adapter = new FileAdapter(TEST_POLICY_PATH);
        SyncedEnforcer enforcer = new SyncedEnforcer(TEST_MODEL_PATH, adapter);

        enforcer.startAutoLoadPolicy(100);

        assertTrue("Auto load should be running", enforcer.isAutoLoadingRunning());

        sleep(300);

        enforcer.stopAutoLoadPolicy();
        assertFalse("Auto load should be stopped", enforcer.isAutoLoadingRunning());
    }

    @Test
    public void testStartAutoLoadPolicyReactsToFileChanges() throws IOException, InterruptedException {
        createPolicyFile("p, alice, data1, read\n");

        SyncedEnforcer enforcer = new SyncedEnforcer(TEST_MODEL_PATH, TEST_POLICY_PATH);
        assertTrue(enforcer.enforce("alice", "data1", "read"));
        assertFalse(enforcer.enforce("alice", "data1", "write"));

        enforcer.startAutoLoadPolicy(100); // Check every 100ms

        // Wait for the watcher thread to be ready
        sleep(200);

        // Update the policy file externally
        createPolicyFile("p, alice, data1, write\n");

        // Wait for the auto-load to pick up the change
        sleep(300);

        assertFalse(enforcer.enforce("alice", "data1", "read"));
        assertTrue(enforcer.enforce("alice", "data1", "write"));

        enforcer.stopAutoLoadPolicy();
    }

    @Test
    public void testStartAutoLoadPolicyCalledTwice() {
        SyncedEnforcer enforcer = new SyncedEnforcer(TEST_MODEL_PATH, TEST_POLICY_PATH);

        enforcer.startAutoLoadPolicy(1000);
        boolean firstState = enforcer.isAutoLoadingRunning();
        int threadCountBefore = Thread.activeCount();

        // Attempt to start again while already running
        enforcer.startAutoLoadPolicy(1000);

        int threadCountAfter = Thread.activeCount();
        boolean secondState = enforcer.isAutoLoadingRunning();

        // State should remain true
        assertTrue(firstState);
        assertTrue(secondState);

        // Ensure no new thread was spawned for the same auto-load logic (count should be stable)
        assertEquals("Calling startAutoLoadPolicy twice should not spawn additional loader threads", 
                     threadCountBefore, threadCountAfter);

        enforcer.stopAutoLoadPolicy();
    }

    @Test
    public void testStartAutoLoadPolicyWithZeroDuration() {
        SyncedEnforcer enforcer = new SyncedEnforcer(TEST_MODEL_PATH, TEST_POLICY_PATH);

        // Spec 0 duration effectively means tight loop or immediate execution
        enforcer.startAutoLoadPolicy(0);

        assertTrue(enforcer.isAutoLoadingRunning());

        // It should be running, we must stop it immediately to prevent CPU saturation
        enforcer.stopAutoLoadPolicy();

        assertFalse(enforcer.isAutoLoadingRunning());
    }

    @Test
    public void testAutoLoadThreadContinuesAfterInterrupt() throws InterruptedException {
        SyncedEnforcer enforcer = new SyncedEnforcer(TEST_MODEL_PATH, TEST_POLICY_PATH);
        final AtomicBoolean loadCalled = new AtomicBoolean(false);

        // Since we can't easily mock loadPolicy in the main class without PowerMock,
        // we verify behavior by observing the thread state.
        enforcer.startAutoLoadPolicy(500); // 500ms interval

        sleep(100);
        assertTrue(enforcer.isAutoLoadingRunning());

        // Trigger an interrupt to the thread to ensure it exits gracefully or handles it
        // We simulate stopping, which interrupts the thread
        enforcer.stopAutoLoadPolicy();

        sleep(100);
        assertFalse("Auto load should be stopped after interrupt", enforcer.isAutoLoadingRunning());
    }

    private void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

