public class RemoveMatchesTests {

    private Role roleA;
    private Role roleB;
    private Role roleC;

    @Before
    public void setUp() throws Exception {
        roleA = createRole("roleA");
        roleB = createRole("roleB");
        roleC = createRole("roleC");
    }

    /**
     * Helper method to create a Role instance using reflection to access the protected constructor.
     */
    private Role createRole(String name) throws Exception {
