     * Helper method to get the 'matched' map from a Role instance.
     */
    @SuppressWarnings("unchecked")
    private Map<String, Role> getMatchedMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matched");
        field.setAccessible(true);
        return (Map<String, Role>) field.get(role);
    }

    /**
     * Helper method to get the 'matchedBy' map from a Role instance.
     */
    @SuppressWarnings("unchecked")
    private Map<String, Role> getMatchedByMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matchedBy");
        field.setAccessible(true);
        return (Map<String, Role>) field.get(role);
    }

    @Test
    public void testRemoveMatches_EmptyMaps() throws Exception {
        // Precondition: roleA has empty matched and matchedBy maps
        Map<String, Role> matchedByA = getMatchedByMap(roleA);
        assertTrue("matchedBy should be empty initially", matchedByA.isEmpty());

        // Action
        roleA.removeMatches();

        // Postcondition: matchedBy should still be empty
        assertTrue("matchedBy should be empty after removeMatches", matchedByA.isEmpty());
    }

    @Test
    public void testRemoveMatches_SingleMatch() throws Exception {
        // Setup: roleB matches roleA (so roleA is matchedBy roleB)
        Map<String, Role> matchedByA = getMatchedByMap(roleA);
        Map<String, Role> matchedB = getMatchedMap(roleB);

        matchedByA.put(roleB.name, roleB);
        matchedB.put(roleA.name, roleA);

        assertEquals(1, matchedByA.size());
        assertEquals(1, matchedB.size());

        // Action
        roleA.removeMatches();

        // Postconditions
        assertTrue("matchedBy of roleA should be empty", matchedByA.isEmpty());
        assertFalse("matched of roleB should not contain roleA", matchedB.containsKey(roleA.name));
        assertTrue("matched of roleB should be empty", matchedB.isEmpty());
    }

    @Test
    public void testRemoveMatches_MultipleMatches() throws Exception {
        // Setup: roleB and roleC match roleA
        Map<String, Role> matchedByA = getMatchedByMap(roleA);
        Map<String, Role> matchedB = getMatchedMap(roleB);
        Map<String, Role> matchedC = getMatchedMap(roleC);

        matchedByA.put(roleB.name, roleB);
        matchedByA.put(roleC.name, roleC);

        matchedB.put(roleA.name, roleA);
        matchedC.put(roleA.name, roleA);

        assertEquals(2, matchedByA.size());
        assertEquals(1, matchedB.size());
        assertEquals(1, matchedC.size());

        // Action
        roleA.removeMatches();

        // Postconditions
        assertTrue("matchedBy of roleA should be empty", matchedByA.isEmpty());
        assertFalse("matched of roleB should not contain roleA", matchedB.containsKey(roleA.name));
        assertFalse("matched of roleC should not contain roleA", matchedC.containsKey(roleA.name));
    }

    @Test
    public void testRemoveMatches_DoesNotClearOtherMatchesInSourceRoles() throws Exception {
        // Setup: roleA is matchedBy roleB. 
        // roleB also matches roleC (roleC is in roleB's matched map).
        Map<String, Role> matchedByA = getMatchedByMap(roleA);
        Map<String, Role> matchedB = getMatchedMap(roleB);

        Map<String, Role> matchedByC = getMatchedByMap(roleC);
        Map<String, Role> matchedC = getMatchedMap(roleC);

        // Establish link: B -> A
        matchedByA.put(roleB.name, roleB);
        matchedB.put(roleA.name, roleA);

        // Establish link: B -> C
        matchedByC.put(roleB.name, roleB);
        matchedB.put(roleC.name, roleC);

        assertEquals(2, matchedB.size()); // B matches A and C

        // Action: Remove matches for A
        roleA.removeMatches();

        // Postconditions: A is removed from B's matches, but C remains
        assertFalse("matched of roleB should not contain roleA", matchedB.containsKey(roleA.name));
        assertTrue("matched of roleB should still contain roleC", matchedB.containsKey(roleC.name));
        assertEquals(1, matchedB.size());
    }

    @Test
    public void testRemoveMatches_SymmetricRemoval() throws Exception {
        // Setup: A <-> B (A is in B's matched, B is in A's matched)
        Map<String, Role> matchedByA = getMatchedByMap(roleA);
        Map<String, Role> matchedA = getMatchedMap(roleA);

        Map<String, Role> matchedByB = getMatchedByMap(roleB);
        Map<String, Role> matchedB = getMatchedMap(roleB);

        // A matches B
        matchedByB.put(roleA.name, roleA);
        matchedA.put(roleB.name, roleB);

        // B matches A
        matchedByA.put(roleB.name, roleB);
        matchedB.put(roleA.name, roleA);

        // Action
        roleA.removeMatches();

        // Postconditions for A
        assertTrue("matchedBy of roleA should be empty", matchedByA.isEmpty());

        // Postconditions for B (the role that was matching A)
        assertFalse("matched of roleB should not contain roleA", matchedB.containsKey(roleA.name));

        // Invariant: A's matched map is not cleared by removeMatches, only matchedBy.
        // The spec says "removes the current instance's name from each role's matched map"
        // and "clears the matchedBy map". It does not say it clears 'this.matched'.
        assertTrue("matched of roleA should still contain roleB (unchanged)", matchedA.containsKey(roleB.name));
    }
}

